class BoundedQueue:
    def __init__(self, capacity):
        self._slots = [None] * capacity      # allocated once, reused for ever
        self._head = 0                       # index of the oldest item
        self._count = 0                      # how many items are inside

    def offer(self, item):
        if self._count == len(self._slots):
            return False
        tail = (self._head + self._count) % len(self._slots)    # the % wraps the index past the end back to 0
        self._slots[tail] = item
        self._count += 1
        return True

    def poll(self):
        if self._count == 0:
            return None
        item = self._slots[self._head]
        self._slots[self._head] = None       # do not keep a reference to an item that has left the queue
        self._head = (self._head + 1) % len(self._slots)
        self._count -= 1
        return item

    def size(self):
        return self._count
